<template>
  <main class="tool-page">
    <div class="shell">
      <header class="page-header">
        <div class="brand"><span class="mark">矩</span><div><b>创新中心 OS · 工具矩阵</b><small>TOOL MATRIX</small></div></div>
        <div class="header-actions"><span>{{ auth.user?.username }}</span><button type="button" @click="returnToOs()">返回 OS 主页</button></div>
      </header>

      <section class="hero">
        <div><span class="eyebrow">SHARE · DISCOVER · BUILD</span><h1>工具<span>矩阵</span></h1><p>把好用的插件、Skill、小程序和工作方法沉淀下来，让探索变成团队共同能力。</p><div class="hero-actions"><button v-if="meta.canSubmit" class="primary" type="button" @click="openCreate">＋ 分享一个工具</button><button type="button" @click="scrollToTools">浏览全部工具</button></div></div>
        <div class="hero-stats"><div><strong>{{ stats.totals.toolCount || 0 }}</strong><span>收录工具</span></div><div><strong>{{ stats.totals.useCount || 0 }}</strong><span>累计使用</span></div><div><strong>{{ stats.totals.contributorCount || 0 }}</strong><span>贡献同事</span></div></div>
      </section>

      <section class="boards">
        <div class="panel hot-panel"><div class="panel-head"><h2>热门工具</h2><span>使用与收藏共同计入热度</span></div><div class="hot-list"><button v-for="(item,index) in stats.topItems" :key="item.id" type="button" @click="openDetail(item.id)"><i :style="toolColors(item)">{{ item.icon }}</i><span><b>{{ item.name }}</b><small>{{ item.type }} · {{ item.source }}</small></span><strong>NO.{{ index+1 }} · {{ item.heat }}</strong></button></div></div>
        <div class="panel"><div class="panel-head"><h2>开发达人</h2><span>仅统计团队自研</span></div><div v-if="stats.developers.length" class="rank-list"><div v-for="(item,index) in stats.developers" :key="item.name"><i>{{ item.name.slice(0,1) }}</i><span><b>{{ item.name }}</b><small>自研 {{ item.count }} 个工具</small></span><strong>NO.{{ index+1 }}</strong></div></div><div v-else class="rank-empty">暂无团队自研排名</div></div>
        <div class="panel"><div class="panel-head"><h2>分享达人</h2><span>发现、整理与教程贡献</span></div><div class="rank-list"><div v-for="(item,index) in stats.contributors" :key="item.name"><i class="green">{{ index+1 }}</i><span><b>{{ item.name }}</b><small>贡献 {{ item.count }} 个工具</small></span><strong>NO.{{ index+1 }}</strong></div></div></div>
      </section>

      <section id="allTools" class="tool-section">
        <div class="toolbar">
          <input v-model="filters.q" placeholder="搜索工具、功能、开发人或贡献人…" @input="scheduleLoad">
          <div class="filter-row"><span>工具类型</span><button :class="{active:!filters.type}" @click="setFilter('type','')">全部</button><button v-for="item in meta.types" :key="item" :class="{active:filters.type===item}" @click="setFilter('type',item)">{{ item }}</button></div>
          <div class="filter-row"><span>来源</span><button :class="{active:!filters.source}" @click="setFilter('source','')">全部</button><button v-for="item in meta.sources" :key="item" :class="{active:filters.source===item}" @click="setFilter('source',item)">{{ item }}</button></div>
          <div class="filter-row"><span>使用场景</span><button :class="{active:!filters.scene}" @click="setFilter('scene','')">全部</button><button v-for="item in meta.scenes" :key="item" :class="{active:filters.scene===item}" @click="setFilter('scene',item)">{{ item }}</button></div>
        </div>
        <div class="section-title"><div><h2>全部工具</h2><p>点击卡片查看功能、使用方法和获取方式</p></div><span>共 {{ items.length }} 个</span></div>
        <div v-if="loading" class="empty">正在加载工具…</div><div v-else-if="!items.length" class="empty">暂时没有符合条件的工具</div>
        <div v-else class="tool-grid"><button v-for="item in items" :key="item.id" class="tool-card" type="button" @click="openDetail(item.id)"><div class="tool-top"><i :style="toolColors(item)">{{ item.icon }}</i><span>{{ item.source }}</span></div><h3>{{ item.name }}</h3><small>{{ item.englishName }}</small><p>{{ item.summary }}</p><div class="tags"><span>{{ item.type }}</span><span>{{ item.scene }}</span></div><div class="tool-meta"><span>开发：{{ item.developerName || '未填写' }}<br>贡献：{{ item.contributorName }}</span><strong>↗ {{ item.heat }} 热度</strong></div></button></div>
      </section>

      <section class="usage"><div class="usage-head"><div><h2>工具类型使用频率</h2><p>根据团队实际打开和下载次数自动统计</p></div><span class="eyebrow">TOOL PULSE</span></div><div class="bar-chart"><div v-for="type in meta.types" :key="type" class="bar-item"><div class="bar" :style="{height:barHeight(type)}"><strong>{{ usageCount(type) }}</strong></div><b>{{ type }}</b></div></div></section>
    </div>

    <div v-if="detailOpen" class="overlay" @click.self="closeDetail">
      <section class="detail-modal"><button class="close" type="button" @click="closeDetail">×</button><div class="detail-visual" :style="toolColors(detail)"><i>{{ detail.icon }}</i><span class="eyebrow">TOOL DETAIL</span><h2>{{ detail.name }}</h2><p>{{ detail.summary }}</p></div><div class="detail-body"><div class="badges"><span>{{ detail.type }}</span><span>{{ detail.source }}</span><span>{{ detail.scene }}</span></div><dl><dt>开发人</dt><dd>{{ detail.developerName || '未填写' }}</dd><dt>贡献人</dt><dd>{{ detail.contributorName }}</dd><dt>综合热度</dt><dd>{{ detail.heat }}</dd><dt>获取方式</dt><dd>{{ [detail.officialUrl?'官方链接':'',detail.packageName||''].filter(Boolean).join('、') }}</dd></dl><h3>主要功能</h3><p>{{ detail.functionDescription }}</p><h3>使用方法</h3><ol><li v-for="step in detail.usageSteps" :key="step">{{ step }}</li></ol><h3>版本与安全说明</h3><p>{{ detail.versionDescription || '暂无版本说明' }}</p><div class="detail-actions"><button v-if="detail.officialUrl" class="primary" type="button" @click="openOfficial">打开官方链接</button><button v-if="detail.packageName" class="primary" type="button" @click="downloadPackage">下载工具文件</button><button type="button" @click="toggleFavorite">{{ detail.favoritedByMe ? '♥ 已收藏' : '♡ 收藏工具' }}</button></div><div v-if="detail.canManage" class="manage-actions"><button type="button" @click="openEdit">修改内容</button><button class="danger" type="button" @click="removeCurrent">删除工具</button></div></div></section>
    </div>

    <div v-if="drawerOpen" class="drawer" @click.self="closeDrawer">
      <form class="form" @submit.prevent="submit"><button class="close" type="button" @click="closeDrawer">×</button><h2>{{ editingId ? '修改工具内容' : '分享一个工具' }}</h2><p>贡献人自动记录为当前登录账号；发布后，贡献人、团队开发人、VIP及管理员可修改或删除。</p>
        <div class="two"><label>工具名称 *<input v-model.trim="form.name" maxlength="100" required></label><label>英文名称<input v-model.trim="form.englishName" maxlength="120"></label></div>
        <div class="two"><label>工具类型 *<select v-model="form.type" required><option value="">请选择</option><option v-for="item in meta.types" :key="item">{{ item }}</option></select></label><label>来源 *<select v-model="form.source" required><option value="">请选择</option><option v-for="item in meta.sources" :key="item">{{ item }}</option></select></label></div>
        <div class="two"><label>使用场景 *<select v-model="form.scene" required><option value="">请选择</option><option v-for="item in meta.scenes" :key="item">{{ item }}</option></select></label><label v-if="isInternal">团队开发人{{ form.source==='团队自研' ? ' *' : '' }}<select v-model="form.developerUserId" :required="form.source==='团队自研'"><option value="">请选择团队成员</option><option v-for="person in meta.teamMembers" :key="person.id" :value="String(person.id)">{{ person.name }}</option></select></label><label v-else>外部开发人 / 作者<input v-model.trim="form.developerName" maxlength="120"></label></div>
        <label>开源或官方网站链接（选填）<input v-model.trim="form.officialUrl" type="url" placeholder="https://..."></label>
        <label>上传工具文件 {{ isInternal && !editingId ? '*' : '（选填）' }}<input ref="packageInput" type="file" accept=".zip,.7z,.rar,.skill,.vsix,.exe,.msi,.dmg,.pkg,.appimage,.apk" :required="isInternal && !editingId"><small class="field-tip">小程序、插件、Skill 或安装包可直接上传供团队下载；官方链接和文件至少提供一项。{{ editingId && detail.packageName ? `当前文件：${detail.packageName}` : '' }}</small></label>
        <label>一句话功能 *<input v-model.trim="form.summary" maxlength="200" required></label><label>功能介绍 *<textarea v-model.trim="form.functionDescription" maxlength="5000" required></textarea></label><label>使用方法 *<textarea v-model.trim="form.usageSteps" maxlength="5000" required placeholder="每一步请换行填写"></textarea></label><label>版本与安全说明<textarea v-model.trim="form.versionDescription" maxlength="1000"></textarea></label>
        <button class="submit-button" type="submit" :disabled="submitting">{{ submitting ? '正在保存…' : (editingId ? '保存修改' : '发布到工具矩阵') }}</button>
      </form>
    </div>
  </main>
</template>

<script setup>
import { computed, onMounted, onUnmounted, reactive, ref } from 'vue';
import { message, Modal } from 'ant-design-vue';
import api from '../platform/api';
import { identity as auth } from '../platform/identity';
import { returnToOs } from '../platform/navigation';


const items=ref([]),loading=ref(false),detailOpen=ref(false),drawerOpen=ref(false),submitting=ref(false),editingId=ref(null),detail=ref({}),packageInput=ref(null);
const meta=reactive({types:[],sources:[],scenes:[],teamMembers:[],canSubmit:false});
const stats=reactive({totals:{},topItems:[],developers:[],contributors:[],usageByType:[]});
const filters=reactive({type:'',source:'',scene:'',q:''});
const emptyForm=()=>({name:'',englishName:'',type:'Agent Skill',source:'开源项目',scene:'设计创作',developerUserId:'',developerName:'',officialUrl:'',summary:'',functionDescription:'',usageSteps:'',versionDescription:''});
const form=reactive(emptyForm());
const isInternal=computed(()=>['团队自研','团队改进版'].includes(form.source));
let searchTimer;
async function loadMeta(){Object.assign(meta,await api.get('/tool-matrix/meta'))}
async function loadStats(){Object.assign(stats,await api.get('/tool-matrix/stats'))}
async function loadItems(){loading.value=true;try{items.value=await api.get('/tool-matrix/items',{params:{...filters}})}finally{loading.value=false}}
async function loadAll(){await Promise.all([loadMeta(),loadStats(),loadItems()])}
function scheduleLoad(){clearTimeout(searchTimer);searchTimer=setTimeout(loadItems,250)}
function setFilter(key,value){filters[key]=value;loadItems()}
function scrollToTools(){document.getElementById('allTools')?.scrollIntoView({behavior:'smooth'})}
async function openDetail(id){detail.value=await api.get(`/tool-matrix/${id}`);detailOpen.value=true;document.body.style.overflow='hidden'}
function closeDetail(){detailOpen.value=false;document.body.style.overflow=''}
function resetForm(){Object.assign(form,emptyForm());if(packageInput.value)packageInput.value.value=''}
function openCreate(){editingId.value=null;resetForm();drawerOpen.value=true;document.body.style.overflow='hidden'}
function closeDrawer(){drawerOpen.value=false;editingId.value=null;document.body.style.overflow=''}
function openEdit(){editingId.value=detail.value.id;Object.assign(form,{name:detail.value.name,englishName:detail.value.englishName,type:detail.value.type,source:detail.value.source,scene:detail.value.scene,developerUserId:detail.value.developerUserId?String(detail.value.developerUserId):'',developerName:detail.value.developerName,officialUrl:detail.value.officialUrl,summary:detail.value.summary,functionDescription:detail.value.functionDescription,usageSteps:detail.value.usageSteps.join('\n'),versionDescription:detail.value.versionDescription});closeDetail();drawerOpen.value=true;document.body.style.overflow='hidden'}
async function submit(){const file=packageInput.value?.files?.[0],existingPackage=Boolean(editingId.value&&detail.value.packageName);if(!isInternal.value&&!form.officialUrl&&!file&&!existingPackage)return message.warning('请至少填写官方链接或上传工具文件');const data=new FormData();for(const [key,value] of Object.entries(form))data.append(key,value);if(file)data.append('package',file);submitting.value=true;try{if(editingId.value)await api.put(`/tool-matrix/${editingId.value}`,data,{headers:{'Content-Type':'multipart/form-data'},timeout:180000});else await api.post('/tool-matrix',data,{headers:{'Content-Type':'multipart/form-data'},timeout:180000});message.success(editingId.value?'工具内容已更新':'工具已发布到矩阵');closeDrawer();resetForm();await loadAll()}catch(error){message.error(error?.error||'保存失败')}finally{submitting.value=false}}
async function openOfficial(){try{const result=await api.post(`/tool-matrix/${detail.value.id}/use`);window.open(result.officialUrl,'_blank','noopener');await Promise.all([loadItems(),loadStats()])}catch(error){message.error(error?.error||'暂时无法打开链接')}}
function downloadPackage(){const link=document.createElement('a');link.href=`/api/tool-matrix/${detail.value.id}/package`;link.download=detail.value.packageName;document.body.appendChild(link);link.click();link.remove();later(()=>Promise.all([loadItems(),loadStats()]).catch(()=>{}),600)}
async function toggleFavorite(){try{const result=await api.post(`/tool-matrix/${detail.value.id}/favorite`);detail.value.favoritedByMe=result.favorited;detail.value.favoriteCount=result.favoriteCount;detail.value.heat=result.heat;message.success(result.favorited?'已收藏工具':'已取消收藏');await Promise.all([loadItems(),loadStats()])}catch(error){message.error(error?.error||'操作失败')}}
function removeCurrent(){Modal.confirm({title:`确认删除“${detail.value.name}”？`,content:'删除后将不再显示在工具矩阵中。',okText:'确认删除',cancelText:'取消',okType:'danger',async onOk(){await api.delete(`/tool-matrix/${detail.value.id}`);message.success('工具已删除');closeDetail();await loadAll()}})}
function usageCount(type){return Number(stats.usageByType.find(item=>item.type===type)?.count||0)}
function barHeight(type){const max=Math.max(1,...meta.types.map(usageCount));return `${Math.max(3,usageCount(type)/max*190)}px`}
function toolColors(item){const palettes=[['#5142b8','#8d72ee'],['#147f78','#55c8b7'],['#b65764','#e98a78'],['#8a4b99','#c77bd7'],['#315a9f','#70a0e4'],['#ef6654','#9b62e8'],['#34313d','#716b7b'],['#d28538','#f0b969']];const id=Number(item?.id)||0;const [c1,c2]=palettes[Math.abs(id-1)%palettes.length];return {'--tool-c1':c1,'--tool-c2':c2}}
let disposed=false;
const pendingTimers=new Set();
function later(task,delay){const id=setTimeout(()=>{pendingTimers.delete(id);if(!disposed)task();},delay);pendingTimers.add(id);}
onMounted(()=>loadAll().catch(error=>message.error(error?.error||'工具加载失败')));
onUnmounted(()=>{disposed=true;clearTimeout(searchTimer);for(const id of pendingTimers)clearTimeout(id);document.body.style.overflow='';});
</script>

<style scoped>
.tool-page{min-height:100vh;color:#24213a;background:radial-gradient(circle at 88% 4%,#e8e4ff 0,transparent 30%),linear-gradient(180deg,#fbfaff,#f4f3f9 65%,#efedf7);--purple:#6657df;--muted:#7a7690;--line:#e9e7f2;--shadow:0 18px 50px rgba(48,39,94,.12)}*{box-sizing:border-box}.shell{width:min(1540px,calc(100% - 48px));margin:auto}.page-header{height:82px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(95,84,160,.13)}.brand{display:flex;align-items:center;gap:14px}.mark{width:40px;height:40px;border-radius:12px;background:linear-gradient(145deg,#493aaf,#806af1);display:grid;place-items:center;color:#fff;font-weight:900;box-shadow:0 10px 24px #6255d944}.brand b,.brand small{display:block}.brand small{color:var(--muted);letter-spacing:2px;margin-top:2px}.header-actions{display:flex;align-items:center;gap:15px;color:var(--muted)}button{font:inherit;cursor:pointer}.header-actions button,.hero-actions button{border:1px solid var(--line);background:#fff;padding:11px 17px;border-radius:12px;color:#24213a}.hero{padding:58px 0 30px;display:grid;grid-template-columns:1.2fr .8fr;gap:42px;align-items:end}.eyebrow{color:var(--purple);font-size:11px;font-weight:800;letter-spacing:4px}.hero h1{font-size:clamp(48px,6vw,84px);line-height:1;margin:16px 0 18px;letter-spacing:-5px}.hero h1 span{color:var(--purple)}.hero p{font-size:17px;line-height:1.9;color:var(--muted);max-width:760px;margin:0}.hero-actions{display:flex;gap:12px;margin-top:25px}.hero-actions .primary,.detail-actions .primary{border:0;background:linear-gradient(120deg,var(--purple),#8c63ed);color:#fff;font-weight:800;box-shadow:0 10px 25px #6657df3d}.hero-stats{display:grid;grid-template-columns:repeat(3,1fr);background:#fff;border:1px solid var(--line);border-radius:22px;box-shadow:var(--shadow);overflow:hidden}.hero-stats>div{padding:24px 20px;border-right:1px solid var(--line)}.hero-stats>div:last-child{border:0}.hero-stats strong,.hero-stats span{display:block}.hero-stats 